import { outdent } from "@cspotcode/outdent";
import { camelCase } from "@mesqueeb/case-anything";
import { BaseClientGenerator } from "./base_generator.ts";
import type { TypeScriptTypeGenerator, ZodSchemaGenerator } from "./schema/mod.ts";
import type { OpenAPISpec } from "./types/mod.ts";

/**
 * Generates a functional TypeScript API client from OpenAPI specifications.
 *
 * This generator creates a collection of standalone functions, one for each API operation.
 * Functions are named based on their operationId (if available) or auto-generated from
 * the method and path. This approach provides excellent tree-shaking capabilities as
 * bundlers can eliminate unused operations.
 *
 * The generated client provides two ways to use it:
 * 1. `createClient(config)` - Convenience function that includes all operations (larger bundle)
 * 2. `createCustomClient(config, { op1, op2 })` - Cherry-pick specific operations (better tree-shaking)
 *
 * Generated function structure:
 * ```ts
 * // Individual operation functions
 * export const getPetById = (config, request) => { ... };
 * export const updatePet = (config, request) => { ... };
 *
 * // Convenience client with all operations
 * export function createClient(config) {
 *   return createCustomClient(config, { getPetById, updatePet, ... });
 * }
 * ```
 *
 * Features:
 * - Standalone operation functions for optimal tree-shaking
 * - Auto-generated or operationId-based function names in camelCase
 * - Full type safety with inline request/response types
 * - Optional Zod validation for requests and responses
 * - JSDoc comments from OpenAPI descriptions
 * - Flexible client creation (all operations or custom selection)
 *
 * @example
 * ```ts
 * import { FunctionalClientGenerator } from "./functional_client_generator.ts";
 *
 * const generator = new FunctionalClientGenerator({
 *   validateRequests: true,
 *   validateResponses: true
 * });
 *
 * // Generate from URL
 * await generator.generateFromUrl(
 *   "https://petstore3.swagger.io/api/v3/openapi.json",
 *   "./src/petstore-client.ts"
 * );
 *
 * // Use the generated client - Option 1: All operations (convenience)
 * import { createClient } from "./src/petstore-client.ts";
 *
 * const client = createClient({
 *   baseUrl: "https://petstore3.swagger.io/api/v3"
 * });
 *
 * const response = await client.getPetById({ path: { petId: 1 } });
 *
 * if (response.status === 200) {
 *   console.log(response.body.name);
 * } else if (response.status === 404) {
 *   console.error(response.body.message);
 * }
 *
 * // Option 2: Custom client with specific operations (better tree-shaking)
 * import { createCustomClient, getPetById, updatePet } from "./src/petstore-client.ts";
 *
 * const config = { baseUrl: "https://petstore3.swagger.io/api/v3" };
 * const customClient = createCustomClient(config, { getPetById, updatePet });
 *
 * await customClient.getPetById({ path: { petId: 1 } });
 *
 * // Option 3: Direct function calls (maximum tree-shaking)
 * import { getPetById } from "./src/petstore-client.ts";
 *
 * const response = await getPetById(config, { path: { petId: 1 } });
 * ```
 */
export class FunctionalClientGenerator extends BaseClientGenerator {
  protected generateClient(spec: OpenAPISpec): string {
    const { code: componentSchemas, typeGen, zodGen } = this
      .generateComponentSchemas(
        spec.components?.schemas,
      );

    const { code: operationFunctions, operationNames } = this
      .generateOperationFunctions(spec, typeGen, zodGen);

    return outdent`
      // deno-lint-ignore-file no-explicit-any
      // This file was auto-generated by @brad-jones/open-api-client

      ${this.generateImports()}

      ${componentSchemas}

      ${operationFunctions}

      export { createCustomClient } from "${this.clientImport}";

      /**
       * Create a client with all available operations.
       * This is convenient but will include all operations in your bundle.
       * For better tree-shaking, use createCustomClient() to select specific operations.
       */
      export function createClient(config: OpenAPIClientConfig) {
        return createCustomClient(config, { ${operationNames.join(",")} });
      }
    `;
  }

  private generateImports(): string {
    const imports: string[] = [];

    // Add Zod import if validation is enabled
    if (this.options?.validateRequests || this.options?.validateResponses) {
      imports.push(`import { z } from "${this.zodImport}";`);
    }

    // Add core imports
    imports.push(outdent`
      import {
        openAPIFetch,
        createCustomClient,
        type OpenAPIClientConfig,
        type OpenAPIResponses
      } from "${this.clientImport}";
    `);

    return imports.join("\n");
  }

  private getOperationName(
    method: string,
    path: string,
    operation: Record<string, unknown>,
  ): string {
    // Use operationId if available
    if (operation.operationId && typeof operation.operationId === "string") {
      return camelCase(operation.operationId);
    }

    // Generate from method + path
    // Convert path to camelCase: GET /hello/{name} -> getHelloName
    const pathPart = path
      .replace(/[{}]/g, "") // Remove braces
      .replace(/[^a-zA-Z0-9]/g, " ") // Replace special chars with spaces
      .trim();

    const combined = `${method} ${pathPart}`;
    return camelCase(combined);
  }

  private generateOperationFunctions(
    spec: OpenAPISpec,
    typeGen: TypeScriptTypeGenerator,
    schemaGen: ZodSchemaGenerator,
  ): { code: string; operationNames: string[] } {
    const operations: string[] = [];
    const operationNames: string[] = [];

    for (const [path, pathItem] of Object.entries(spec.paths)) {
      const methods = [
        "get",
        "post",
        "put",
        "delete",
        "patch",
        "head",
        "options",
        "trace",
      ] as const;

      for (const method of methods) {
        const operation = pathItem[method];
        if (!operation) continue;

        try {
          const operationName = this.getOperationName(method, path, operation);
          const operationCode = this.generateOperationFunction(
            typeGen,
            schemaGen,
            operationName,
            path,
            method,
            operation,
            pathItem,
            spec.components,
          );
          operations.push(operationCode);
          operations.push("");
          operationNames.push(operationName);
        } catch (error) {
          // Log error and skip this operation
          console.error(
            `Error generating operation ${method.toUpperCase()} ${path}: ${error}`,
          );
        }
      }
    }

    return { code: operations.join("\n"), operationNames };
  }

  private generateOperationFunction(
    typeGen: TypeScriptTypeGenerator,
    schemaGen: ZodSchemaGenerator,
    operationName: string,
    path: string,
    method: string,
    operation: Record<string, unknown>,
    pathItem: Record<string, unknown>,
    components?: Record<string, unknown>,
  ): string {
    const parts: string[] = [];

    // Add JSDoc comment if operation has summary or description
    const jsdoc = this.generateOperationJSDoc(operation);
    if (jsdoc) {
      parts.push(jsdoc);
    }

    // Generate function signature with inline types
    const { signature, hasRequest } = this.generateOperationSignature(
      typeGen,
      operationName,
      path,
      method,
      operation,
      pathItem,
      components,
    );

    parts.push(signature);

    // Generate function body
    const body = this.generateOperationBody(
      schemaGen,
      path,
      method,
      operation,
      pathItem,
      hasRequest,
      components,
    );
    parts.push(body);

    return parts.join("\n");
  }

  protected generateOperationSignature(
    typeGen: TypeScriptTypeGenerator,
    operationName: string,
    path: string,
    method: string,
    operation: Record<string, unknown>,
    pathItem: Record<string, unknown>,
    components?: Record<string, unknown>,
  ): { signature: string; hasRequest: boolean } {
    const { hasRequest, requestType } = this.buildRequestSignature(
      typeGen,
      path,
      method,
      operation,
      pathItem,
      components,
    );

    const responseType = this.generateResponseTypeInline(operation, typeGen);

    const params: string[] = [];
    params.push("config: OpenAPIClientConfig");
    if (hasRequest) {
      params.push(requestType);
    }

    const signature = `export const ${operationName} = (${
      params.join(", ")
    }): Promise<OpenAPIResponses<${responseType}>> =>`;

    return { signature, hasRequest };
  }

  protected generateOperationBody(
    schemaGen: ZodSchemaGenerator,
    path: string,
    method: string,
    operation: Record<string, unknown>,
    pathItem: Record<string, unknown>,
    hasRequest: boolean,
    components?: Record<string, unknown>,
  ): string {
    const parts: string[] = [];

    // Generate metadata object
    const metadata = this.generateOperationMetadata(
      schemaGen,
      path,
      method,
      operation,
      pathItem,
      components,
    );

    parts.push("openAPIFetch(");
    parts.push("config");
    parts.push(",");
    parts.push(metadata);

    // Add request parameter if needed
    if (hasRequest) {
      parts.push(",");
      parts.push("request");
    }

    parts.push(") as any;");

    return parts.join("\n");
  }
}
